#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

void dummy() {}
int printheap(int N) { return N; }

struct Edge {
    int u, v, w;
    bool operator<(const Edge& o) const {
        return w > o.w;
    }
};

int parent_arr[5005];

int find_root(int x) {
    return parent_arr[x] == x ? x : (parent_arr[x] = find_root(parent_arr[x]));
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int t;
    if (!(cin >> t)) return 0;
    while (t--) {
        int n, m;
        cin >> n >> m;
        for (int i = 1; i <= n; i++) parent_arr[i] = i;
        vector<Edge> edges(m);
        for (int i = 0; i < m; i++) {
            cin >> edges[i].u >> edges[i].v >> edges[i].w;
        }
        sort(edges.begin(), edges.end());
        long long ans = 0;
        int count = 0;
        for (int i = 0; i < m; i++) {
            int ru = find_root(edges[i].u);
            int rv = find_root(edges[i].v);
            if (ru != rv) {
                parent_arr[ru] = rv;
                ans += edges[i].w;
                count++;
                if (count == n - 1) break;
            }
        }
        cout << ans << "\n";
    }
    return 0;
}
